function validate([tasks, sessionTime]) {
  if (!Array.isArray(tasks) || tasks.length < 1 || tasks.length > 14) return 'tasks needs 1 to 14 values.';
  if (tasks.some(t => !Number.isInteger(t) || t < 1 || t > 10)) return 'Each task takes 1 to 10 hours.';
  if (!Number.isInteger(sessionTime) || sessionTime > 15) return 'sessionTime is at most 15.';
  if (sessionTime < Math.max(...tasks)) return 'sessionTime must be at least the longest task.';
  return null;
}

