function minSessions(tasks, sessionTime) {
  const n = tasks.length;
  const full = 1 << n;
  const sessions = new Array(full).fill(Infinity);
  const used = new Array(full).fill(Infinity);
  sessions[0] = 1;
  used[0] = 0;
  for (let mask = 0; mask < full; mask++) {
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        continue;
      }
      const next = mask | (1 << i);
      let count = sessions[mask];
      let time = used[mask] + tasks[i];
      if (time > sessionTime) {
        count++;
        time = tasks[i];
      }
      if (count < sessions[next] || (count === sessions[next] && time < used[next])) {
        sessions[next] = count;
        used[next] = time;
      }
    }
  }
  return sessions[full - 1];
}

