function minSessions(tasks, sessionTime) {
  // best[set] = fewest sessions for the tasks in set, choosing the whole last session as a subset at once.
  const n = tasks.length;
  const all = (1 << n) - 1;
  const total = new Array(all + 1).fill(0);
  for (let set = 1; set <= all; set++) {
    for (let i = 0; i < n; i++) if (set & (1 << i)) total[set] += tasks[i];
  }
  const best = new Array(all + 1).fill(Infinity);
  best[0] = 0;
  for (let set = 1; set <= all; set++) {
    for (let last = set; last > 0; last = (last - 1) & set) {
      if (total[last] <= sessionTime) best[set] = Math.min(best[set], best[set ^ last] + 1);
    }
  }
  return best[all];
}

