function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(12, 14) : int(1, 8);
  const top = [3, 6, 10][int(0, 2)];
  const tasks = Array.from({ length: n }, () => int(1, top));
  const largest = Math.max(...tasks);
  const sessionTime = int(largest, 15);
  return [tasks, sessionTime];
}
